 function workflowForm(kind:string){return <form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const a:any=Object.fromEntries(f.entries());a.type=kind;if(kind==='note')a.blocking=f.get('blocking')==='on';if(await action(a))e.currentTarget?.reset()}}>{kind==='note'?<><label className="field">Question or review note</label><textarea name="text" required placeholder="What needs to be clarified?"/><div className="actions"><select name="kind"><option value="question">Client question</option><option value="note">Internal review note</option></select><input name="ref" placeholder="Evidence / return reference"/><label><input type="checkbox" name="blocking"/> Blocks filing</label></div></>:kind==='task'?<><input name="text" required placeholder="Task description" style={{width:'100%'}}/><div className="actions" style={{marginTop:10}}><select name="owner">{users.map((u:any)=><option key={u.id} value={u.id}>{u.name}</option>)}</select><input type="date" name="due" required/></div></>:null}<button disabled={busy} className="btn primary" style={{marginTop:12}}>Save {kind==='note'?'question / note':'task'}</button></form>}
