 {record==='Return lines'&&<div className="tablewrap"><table><thead><tr><th>Reference</th><th>Return line</th><th className="num">2024 value</th><th className="num">Engine value</th><th className="num">Working value</th><th>Review</th></tr></thead><tbody>{v.lines.filter((l:any)=>(form==='all'||l.form===form)&&JSON.stringify(l).toLowerCase().includes(query.toLowerCase())).slice(linePage*50,(linePage+1)*50).map((l:any)=><tr className="clickable" key={l.key} onClick={()=>trace(l.key)}><td>{l.key}</td><td>{l.label}</td><td className="num">{money(p.prior_years.return_2024.lines[l.key])}</td><td className="num">{money(l.value)}</td><td className="num">{money(version==='v3'?currentValue(l):l.value)}</td><td><span className={'pill '+(verified.has(l.key)?'green':'')}>{verified.has(l.key)?'Verified':'To review'}</span></td></tr>)}</tbody></table><div className="row"><Button onClick={()=>setLinePage(Math.max(0,linePage-1))}>Previous</Button><span>Page {linePage+1} · 50 lines per page</span><Button onClick={()=>{const n=v.lines.filter((l:any)=>(form==='all'||l.form===form)&&JSON.stringify(l).toLowerCase().includes(query.toLowerCase())).length;if((linePage+1)*50<n)setLinePage(linePage+1)}}>Next</Button></div></div>}
 {record==='Assets & depreciation'&&v.assets.filter((a:any)=>JSON.stringify(a).toLowerCase().includes(query.toLowerCase())).map((a:any)=><div className="card" key={a.asset_id}><div className="cardhead"><h2>{a.description}</h2>{refButton('asset:'+a.asset_id)}</div><div className="split"><div><p>{a.method} · {a.life_years} years</p><p>Placed in service: {a.placed_in_service}</p><p>Cost: {money(a.cost)}</p></div><div><div className="row">Federal depreciation <strong>{money(a.federal.depreciation_2025)}</strong></div><div className="row">California depreciation <strong>{money(a.california.depreciation_2025)}</strong></div><div className="row">AMT depreciation <strong>{money(a.amt.depreciation_2025)}</strong></div></div></div>{jsonTree({full_asset_record:a})}</div>)}
